@Test
public void testTimeout() throws InterruptedException, EventDeliveryException, InstantiationException, IllegalAccessException {
    setUp();
    Event event = EventBuilder.withBody("foo", Charsets.UTF_8);
    AtomicLong delay = new AtomicLong();
    Server server = createServer(new DelayMockAvroServer(delay));
    server.start();
    sink.start();
    Assert.assertTrue(LifecycleController.waitForOneOf(sink, LifecycleState.START_OR_ERROR, 5000));
    Transaction txn = channel.getTransaction();
    txn.begin();
    for (int i = 0; i < 4; i++) {
        channel.put(event);
    }
    txn.commit();
    txn.close();
    // should throw EventDeliveryException due to connect timeout
    // because connect-timeout = 2000
    delay.set(3000L);
    boolean threw = false;
    try {
        sink.process();
    } catch (EventDeliveryException ex) {
        logger.info("Correctly threw due to connect timeout. Exception follows.", ex);
        threw = true;
    }
    Assert.assertTrue("Must throw due to connect timeout", threw);
    // now, allow the connect handshake to occur
    delay.set(0);
    sink.process();
    // should throw another EventDeliveryException due to request timeout
    // because request-timeout = 3000
    delay.set(4000L);
    threw = false;
    try {
        sink.process();
    } catch (EventDeliveryException ex) {
        logger.info("Correctly threw due to request timeout. Exception follows.", ex);
        threw = true;
    }
    Assert.assertTrue("Must throw due to request timeout", threw);
    sink.stop();
    Assert.assertTrue(LifecycleController.waitForOneOf(sink, LifecycleState.STOP_OR_ERROR, 5000));
    server.close();
    SinkCounter sinkCounter = (SinkCounter) Whitebox.getInternalState(sink, "sinkCounter");
    Assert.assertEquals(2, sinkCounter.getEventWriteFail());
}

