@Test
public void testTimeout() throws Exception {
    AtomicLong delay = new AtomicLong();
    src = new ThriftTestingSource(ThriftTestingSource.HandlerType.ALTERNATE.name(), port, ThriftRpcClient.COMPACT_PROTOCOL);
    src.setDelay(delay);
    delay.set(2500);
    Event event = EventBuilder.withBody("foo", Charsets.UTF_8);
    sink.start();
    Transaction txn = channel.getTransaction();
    txn.begin();
    for (int i = 0; i < 4; i++) {
        channel.put(event);
    }
    txn.commit();
    txn.close();
    // should throw EventDeliveryException due to connect timeout
    boolean threw = false;
    try {
        sink.process();
    } catch (EventDeliveryException ex) {
        threw = true;
    }
    Assert.assertTrue("Must throw due to connect timeout", threw);
    // now, allow the connect handshake to occur
    delay.set(0);
    sink.process();
    // should throw another EventDeliveryException due to request timeout
    // because request-timeout = 2000
    delay.set(2500L);
    threw = false;
    try {
        sink.process();
    } catch (EventDeliveryException ex) {
        threw = true;
    }
    Assert.assertTrue("Must throw due to request timeout", threw);
    sink.stop();
}

