@Test
public void testBatchSize() throws EventDeliveryException {
    DatasetSink sink = sink(in, config);
    // release one record per process call
    config.put("kite.batchSize", "2");
    Configurables.configure(sink, config);
    sink.start();
    // process the first and second
    sink.process();
    // roll at the next process call
    sink.roll();
    // roll and process the third
    sink.process();
    Assert.assertEquals(Sets.newHashSet(expected.subList(0, 2)), read(Datasets.load(FILE_DATASET_URI)));
    Assert.assertEquals("Should have committed", 0, remaining(in));
    // roll at the next process call
    sink.roll();
    // roll, the channel is empty
    sink.process();
    Assert.assertEquals(Sets.newHashSet(expected), read(Datasets.load(FILE_DATASET_URI)));
    sink.stop();
}

